## Submitted testbench
```systemverilog
module tb;
  // ------------------------------------------------------------
  //  Parameters and signal declarations
  // ------------------------------------------------------------
  localparam int CLK_HALF = 4;               // 8 ns period → 125 MHz
  logic        clk          = 0;
  logic        rst          = 0;
  logic [15:0] prescale     = 16'h5;        // default prescale value
  logic        rxd          = 1'b1;        // UART received line
  logic        m_axis_tready = 1'b1;       // always ready for AXI output
  wire [7:0]   m_axis_tdata;
  wire         m_axis_tvalid;
  wire         busy;
  wire         overrun_error;
  wire         frame_error;

  // ------------------------------------------------------------
  //  DUT instantiation (uart_rx)
  // ------------------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd          (rxd),
    .busy         (busy),
    .overrun_error(overrun_error),
    .frame_error  (frame_error),
    .prescale     (prescale)
  );

  // ------------------------------------------------------------
  //  Clock generation
  // ------------------------------------------------------------
  always #CLK_HALF clk = ~clk;

  // ------------------------------------------------------------
  //  Reset sequence
  // ------------------------------------------------------------
  initial begin
    rst = 1'b0;
    #20 rst = 1'b1;
    #20 rst = 1'b0;
    #50;
  end

  // ------------------------------------------------------------
  //  Task: send a frame with an optional glitch inside a data bit
  // ------------------------------------------------------------
  task automatic send_frame(input byte unsigned data, input int glitch_pos);
    int unsigned bit_clks = int'(prescale) * 8;   // clocks per bit

    // ---- start bit (always low) ----
    rxd = 1'b0;
    repeat (bit_clks) @(negedge clk);

    // ---- 8 data bits (MSB‑first) ----
    for (int i = 0; i < 8; i++) begin
      logic [0:0] bit_val;
      bit_val = data[7 - i];                     // MSB first

      if (i == glitch_pos) begin                 // insert glitch here
        repeat (bit_clks - 2) @(negedge clk);    // hold original value
        rxd = ~bit_val;                            // first edge
        @(negedge clk);
        rxd = bit_val;                             // second edge
        @(negedge clk);
      end else begin
        repeat (bit_clks) @(negedge clk);        // normal bit period
        rxd = bit_val;
      end
    end

    // ---- stop bit (high) ----
    rxd = 1'b1;
    repeat (bit_clks) @(negedge clk);

    // wait for the generated m_axis_tvalid to assert
    @(posedge m_axis_tvalid);
  endtask

  // ------------------------------------------------------------
  //  Main stimulus
  // ------------------------------------------------------------
  initial begin
    // ---- wait for reset de‑assertion ----
    wait (!rst);
    #100;  // small margin

    // ---- first frame : 0xA5 with glitch in bit #2 ----
    send_frame(8'hA5, 2);
    #2000;                     // inter‑frame gap (as in reference)

    // ---- second frame : 0x5A with glitch in bit #2 ----
    send_frame(8'h5A, 2);

    // ---- ensure no pending errors before finishing ----
    @(negedge busy);
    #10;
    $finish;                   // end simulation cleanly
  end

endmodule
